CREATE TABLE roles(id INTEGER PRIMARY KEY,code TEXT NOT NULL UNIQUE CHECK(code IN('CUSTOMER','ADMIN')));
INSERT INTO roles(code) VALUES('CUSTOMER'),('ADMIN');
CREATE TABLE users(id INTEGER PRIMARY KEY,role_id INTEGER NOT NULL REFERENCES roles(id),email TEXT NOT NULL UNIQUE CHECK(length(email)<=254 AND email=lower(trim(email))),name TEXT NOT NULL CHECK(length(name) BETWEEN 2 AND 100),phone TEXT CHECK(phone IS NULL OR length(phone) BETWEEN 7 AND 20),password_hash TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(id INTEGER PRIMARY KEY,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER REFERENCES users(id),csrf_token TEXT NOT NULL,created_at TEXT NOT NULL,last_seen_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE addresses(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),recipient TEXT NOT NULL CHECK(length(recipient) BETWEEN 2 AND 100),phone TEXT NOT NULL CHECK(length(phone) BETWEEN 7 AND 20),region TEXT NOT NULL CHECK(length(region) BETWEEN 2 AND 100),province TEXT NOT NULL CHECK(length(province) BETWEEN 2 AND 100),district TEXT NOT NULL CHECK(length(district) BETWEEN 2 AND 100),street TEXT NOT NULL CHECK(length(street) BETWEEN 5 AND 200),reference TEXT CHECK(reference IS NULL OR length(reference)<=200),is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN(0,1)),version INTEGER NOT NULL DEFAULT 1);
